import React from "react";

export default function Policy() {
  return (
    <section className="bg-black text-white py-16 px-6 md:px-16">
      {/* Title */}
      <h1 className="text-center text-4xl md:text-5xl font-extrabold text-[#8944F5] mb-10">
        Privacy Policy & Terms
      </h1>

      {/* Scrollable Content */}
      <div className="max-w-6xl mx-auto bg-[#0c0c0c] rounded-2xl shadow-lg shadow-[#8944F5]/20 p-8 md:p-12 overflow-y-auto max-h-[75vh] custom-scroll">
        {/* Example paragraphs */}
        <p className="mb-6 leading-relaxed text-gray-300">
          Welcome to Live Hunt Share. This Privacy Policy explains how we
          collect, use, and protect your personal information when you use our
          services. By accessing or using Live Hunt Share, you agree to the
          terms described in this policy.
        </p>
        <p className="mb-6 leading-relaxed text-gray-300">
          You are responsible for any content you share while using our live
          streaming, social, or gaming features. Please do not post or share
          anything that violates applicable laws or our community guidelines.
        </p>

        {/* This is where you will paste your big content */}
        <p className="mb-6 leading-relaxed text-gray-300">
        </p>
      </div>

      {/* Back to Top Button */}
      <button
        onClick={() => window.scrollTo({ top: 0, behavior: "smooth" })}
        className="fixed bottom-6 right-6 bg-[#8944F5] hover:bg-[#7736d4] text-white px-4 py-2 rounded-full shadow-md hover:shadow-[#8944F5]/50 transition-all duration-300"
      >
        ↑ Top
      </button>
    </section>
  );
}
